// TAS Digital resource sites — one Worker, two hostnames.
//   resources.tas-digital.ai  the full client library
//   creative.tas-digital.ai   VSL at /, Creative Strategy Playbook at /library
// A row is live when Airtable Status = Posted AND "Publish to" contains
// that site's tag. Deployed by Claude via n8n.

const AIRTABLE_BASE  = "appU32zN67pMhC0IU";
const AIRTABLE_TABLE = "tblymxflXKKk955LI";

// The one value that makes a resource public. Must match the Airtable
// Status choice exactly.
const PUBLISHED_STATUS = "Posted";

// One Worker serves both sites. The hostname decides which. SITES is defined
// at the bottom of this file, next to the page templates.
function siteFor(hostname) {
  return SITES[hostname] || SITES.default;
}

// Rendered pages are memoised per hostname — the token substitution runs once
// per isolate, not once per request.
const RENDER_CACHE = new Map();
function render(site) {
  let hit = RENDER_CACHE.get(site.key);
  if (!hit) {
    hit = INDEX_TPL.replace(/\{\{([A-Z0-9_]+)\}\}/g, (m, token) =>
      token in site.tokens ? site.tokens[token] : m
    );
    RENDER_CACHE.set(site.key, hit);
  }
  return hit;
}

const EDGE_CACHE_SECONDS    = 60;
const BROWSER_CACHE_SECONDS = 30;

const N8N_GATE_WEBHOOK =
  "https://primary-production-1e83.up.railway.app/webhook/lead-magnet-gate";

const IMAGE_PROXY = {
  "/assets/tas-logo-black.png":
    "https://cdn.prod.website-files.com/654e8713431b6e197569c212/6647386838d851201c65f7a0_talas%20logo%201.png",
  "/assets/tas-mark.png":
    "https://cdn.prod.website-files.com/654e8713431b6e197569c212/6554d536c8357781ef074345_tas%20webicon.png",
};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const site = siteFor(url.hostname);

    if (url.pathname === "/api/resources") {
      if (request.method !== "GET") return json({ error: "Method not allowed" }, 405);
      try {
        return await resources(request, env, ctx, site, url.searchParams.has("fresh"));
      } catch (err) {
        console.error("resources error:", err);
        return json({ error: "Failed to load resources" }, 502);
      }
    }

    // Same Airtable feed as /api/resources with the links removed, for the
    // "what's inside" teaser on the VSL page. Shows what you get without
    // handing it over before the form.
    if (url.pathname === "/api/preview") {
      if (request.method !== "GET") return json({ error: "Method not allowed" }, 405);
      try {
        const res = await resources(request, env, ctx, site, url.searchParams.has("fresh"));
        const data = await res.json();
        const items = (data.resources || []).map((r) => ({
          name: r.name,
          summary: r.summary,
          category: r.category,
          type: r.type,
        }));
        return json({ count: items.length, resources: items }, 200, {
          "Cache-Control":
            `public, max-age=${BROWSER_CACHE_SECONDS}, s-maxage=${EDGE_CACHE_SECONDS}`,
        });
      } catch (err) {
        console.error("preview error:", err);
        return json({ error: "Failed to load preview" }, 502);
      }
    }

    if (url.pathname === "/api/gate") {
      if (request.method !== "POST") return json({ error: "Method not allowed" }, 405);
      try {
        return await gate(request);
      } catch (err) {
        console.error("gate error:", err);
        return json({ ok: false }, 502);
      }
    }

    if (IMAGE_PROXY[url.pathname]) {
      try {
        return await proxyImage(url.pathname, request, ctx);
      } catch (err) {
        console.error("image proxy error:", err);
        return new Response("Not found", { status: 404 });
      }
    }

    if (url.pathname === "/library" || url.pathname === "/index.html") {
      return page(render(site));
    }
    if (url.pathname === "/") {
      return page(site.vsl ? VSL_HTML : render(site));
    }
    return new Response("Not found", { status: 404 });
  },
};

// ── /api/resources ──────────────────────────────────────────────────
async function resources(request, env, ctx, site, fresh) {
  const cache = caches.default;
  const cacheKey = new Request(new URL("/api/resources", request.url));

  if (!fresh) {
    const hit = await cache.match(cacheKey);
    if (hit) return hit;
  }

  // Ask Airtable to do the filtering — less data over the wire, and the
  // publish gate is enforced before anything leaves Airtable.
  const formula =
    `AND({Status} = "${PUBLISHED_STATUS}", FIND("${site.tag}", ARRAYJOIN({Publish to}, ",")) > 0)`;

  const records = [];
  let offset;
  do {
    const qs = new URLSearchParams({ pageSize: "100", filterByFormula: formula });
    if (offset) qs.set("offset", offset);

    const res = await fetch(
      `https://api.airtable.com/v0/${AIRTABLE_BASE}/${AIRTABLE_TABLE}?${qs}`,
      { headers: { Authorization: `Bearer ${env.AIRTABLE_TOKEN}` } }
    );
    if (!res.ok) throw new Error(`Airtable responded ${res.status}`);

    const data = await res.json();
    records.push(...data.records);
    offset = data.offset;
  } while (offset);

  const items = records
    .map((r) => ({
      id:          r.id,
      name:        (r.fields.Name || "").trim(),
      summary:     (r.fields.Summary || "").trim(),
      description: (r.fields.Description || "").trim(),
      category:    r.fields.Category || "",
      type:        r.fields.Type || "",
      isNew:       !!r.fields.New,
      link:        (r.fields.Link || "").trim(),
      status:      r.fields.Status || "",
    }))
    // Belt and braces: never serve an unpublished row, and never serve a
    // row that would render a card with nowhere to go.
    .filter((r) => r.status === PUBLISHED_STATUS && r.name && r.link)
    .map(({ status, ...rest }) => rest);

  const response = json(
    { count: items.length, resources: items },
    200,
    {
      "Cache-Control":
        `public, max-age=${BROWSER_CACHE_SECONDS}, s-maxage=${EDGE_CACHE_SECONDS}`,
    }
  );

  if (!fresh) ctx.waitUntil(cache.put(cacheKey, response.clone()));
  return response;
}

// ── /api/gate ───────────────────────────────────────────────────────
async function gate(request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ ok: false, error: "Invalid JSON" }, 400);
  }

  const email = String(body.email || "").trim().toLowerCase().slice(0, 200);
  const name  = String(body.full_name || "").trim().slice(0, 120);
  const website = String(body.website || "").trim().slice(0, 200);

  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    return json({ ok: false, error: "Invalid email" }, 400);
  }

  // Attribution passthrough. Allow-listed so the endpoint can't be used to
  // push arbitrary keys into the CRM, and each value is length-capped.
  const ATTR_KEYS = [
    "utm_source", "utm_medium", "utm_campaign", "utm_content", "utm_term",
    "fbclid", "gclid", "landing_page", "referrer",
  ];
  const attr = {};
  for (const k of ATTR_KEYS) {
    const v = body[k];
    if (typeof v === "string" && v.trim()) attr[k] = v.trim().slice(0, 300);
  }

  const res = await fetch(N8N_GATE_WEBHOOK, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      full_name: name,
      email,
      source: String(body.source || "Creative Strategy Playbook").slice(0, 80),
      website,
      ...attr,
    }),
  });

  return json({ ok: res.ok });
}

// ── image proxy ─────────────────────────────────────────────────────
async function proxyImage(pathname, request, ctx) {
  const cache = caches.default;
  const cacheKey = new Request(new URL(pathname, request.url));

  const hit = await cache.match(cacheKey);
  if (hit) return hit;

  const upstream = await fetch(IMAGE_PROXY[pathname]);
  if (!upstream.ok) throw new Error(`upstream ${upstream.status}`);

  const response = new Response(upstream.body, {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": "public, max-age=86400",
    },
  });
  ctx.waitUntil(cache.put(cacheKey, response.clone()));
  return response;
}

// ── helpers ─────────────────────────────────────────────────────────
function page(html) {
  return new Response(html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "public, max-age=0, must-revalidate",
    },
  });
}

function json(body, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Access-Control-Allow-Origin": "*",
      ...extraHeaders,
    },
  });
}

